package local.skyfamily;
import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
final class SavedAlbums {
 static void show(CalendarPhotosActivity host){host.page("Choose your albums");host.text("Tap album cards to save your selection immediately. No selected albums means Whole library. Up to 12 albums; nothing changes on the Immich server.");final LinkedHashSet<String> selected=host.selection();TextView summary=host.paperText(selected.isEmpty()?"Whole library saved":selected.size()+" saved album(s)",17,PaperActivity.INK);host.body.addView(summary);host.button("Browse saved selection",()->host.library());host.button("Play saved selection",()->host.startGallery(false));host.button("Use whole library",()->{host.choose(new HashSet<String>());show(host);});EditText search=host.input("Search album names","");LinearLayout covers=new LinearLayout(host);covers.setOrientation(1);host.body.addView(covers);final int[] page={0};final Runnable[] render={()->{}};host.button("Previous album page",()->{page[0]=Math.max(0,page[0]-1);render[0].run();});host.button("Next album page",()->{page[0]++;render[0].run();});final String server=host.server,token=host.token;final int stamp=host.revision;host.work(()->{JSONArray response=new JSONArray(new String(host.request(server+"/albums","GET",null,token,6000000),"UTF-8"));ArrayList<JSONObject> albums=new ArrayList<>();for(int i=0;i<response.length();i++){JSONObject album=response.optJSONObject(i);if(album!=null)albums.add(album);}Collections.sort(albums,(a,b)->a.optString("albumName").compareToIgnoreCase(b.optString("albumName")));host.ui.post(()->{if(stamp!=host.revision||!server.equals(host.server)||!token.equals(host.token))return;render[0]=()->{covers.removeAllViews();ArrayList<JSONObject> found=new ArrayList<>();String filter=search.getText().toString().toLowerCase(Locale.getDefault());for(JSONObject album:albums)if(album.optString("albumName").toLowerCase(Locale.getDefault()).contains(filter))found.add(album);int first=Math.min(page[0]*24,Math.max(0,(found.size()-1)/24*24)),columns=host.frameColumns(),count=0;LinearLayout row=null;for(int i=first;i<Math.min(first+24,found.size());i++){JSONObject album=found.get(i);String id=album.optString("id");if(count%columns==0){row=new LinearLayout(host);covers.addView(row);}LinearLayout card=new LinearLayout(host);card.setOrientation(1);card.setPadding(host.dp(12),host.dp(12),host.dp(12),host.dp(12));card.setBackground(host.shape(selected.contains(id)?host.palette().rail:host.palette().surface,selected.contains(id)?PaperActivity.INK:PaperActivity.LINE,16));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-2,1);size.setMargins(host.dp(4),host.dp(4),host.dp(4),host.dp(4));row.addView(card,size);ImageView image=new ImageView(host);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,host.dp(140)));host.thumb(image,server,token,album.optString("albumThumbnailAssetId"));TextView title=host.paperText(album.optString("albumName","Album"),18,PaperActivity.INK);title.setMaxLines(2);card.addView(title);TextView details=host.paperText(album.optInt("assetCount")+" items / "+(selected.contains(id)?"Selected":"Tap to select"),14,PaperActivity.MUTE);card.addView(details);card.setContentDescription(title.getText()+" / "+details.getText());card.setSelected(selected.contains(id));card.setFocusable(true);card.setOnClickListener(view->{if(!server.equals(host.server)||!token.equals(host.token))return;if(selected.contains(id))selected.remove(id);else{if(selected.size()>=12){host.toast("Choose up to 12 albums");return;}selected.add(id);}host.choose(selected);summary.setText(host.selectionSaveFailed?"NOT SAVED / check storage":selected.isEmpty()?"Whole library saved":selected.size()+" album(s) saved");card.setSelected(selected.contains(id));card.setBackground(host.shape(selected.contains(id)?host.palette().rail:host.palette().surface,selected.contains(id)?PaperActivity.INK:PaperActivity.LINE,16));details.setText(album.optInt("assetCount")+" items / "+(selected.contains(id)?"Selected":"Tap to select"));card.setContentDescription(title.getText()+" / "+details.getText());});count++;}if(row!=null&&count%columns!=0)for(int i=count%columns;i<columns;i++)row.addView(new View(host),new LinearLayout.LayoutParams(0,1,1));if(found.isEmpty())covers.addView(host.paperText("No matching albums",18,PaperActivity.MUTE));};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence value,int a,int c,int f){}public void onTextChanged(CharSequence value,int a,int b,int c){page[0]=0;render[0].run();}public void afterTextChanged(Editable value){}});render[0].run();});});}
}
